@Override
public JsonToken nextToken() throws IOException, JsonParseException {
    JsonToken t = delegate.nextToken();

    if (t != null) {
        return t;
    }

    while (_nextParser < _parsers.length) {
        delegate = _parsers[_nextParser++];
        t = delegate.nextToken();
        if (t != null) {
            return t;
        }
    }

    return null;
}
